window.MONSTER_CHUNK_41 = [{"name":"Blightspawn of Ghlaunder","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"aberration","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"auras":["stagnation (20 ft., DC 16)"],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 Dex, +4 natural","hp":52,"hd":"7d8+21","hdvalue":7,"hp_mods":["fast healing 3"],"fort":5,"ref":8,"will":8,"dr":"5/magic","immunities":["acid","cold","poison"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"sting +10 (2d6+7/19-20 plus attach and poison)","space":"5 ft.","reach":"10 ft.","special_attacks":[{"type":"blood drain","details":"1d2 Con"},{"type":"stagnation gaze"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"},{"spell":"pass without trace"}]},{"frequency":"1/day","spells":[{"spell":"bestow curse"},{"spell":"blur"},{"spell":"contagion"},{"spell":"diminish plants"},{"spell":"gust of wind"},{"spell":"hold monster"}]}],"strength":21,"dexterity":18,"constitution":16,"intelligence":7,"wisdom":16,"charisma":15,"baseatk":5,"cmb":10,"cmb_special":"+4 vs. maintain a grapple","cmd":24,"cmd_special":"+8 vs. trip","feats":[{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"}],"skills":[{"skill":"Climb","value":13},{"skill":"Fly","value":14},{"skill":"Perception","value":13}],"languages":["Aklo (cannot speak)"],"sq":[{"type":"no breath"}],"treasure":"none","description_visual":"This human-sized, mosquitolike creature has a long, flexible proboscis that ends in a murderous stinger.","source":"The Feast Of Ravenmoor","special_abilities":[{"type":"Poison","kind":"Su","details":"Sting-injury; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d4 Wisdom damage and confusion for 1 round; cure 2 saves. The save DC is Constitution-based."},{"type":"Stagnation Aura","kind":"Su","details":"A blightspawn's stagnation aura causes lethargy and torpor in those who approach it, sapping energy and speed. When a creature comes within 20 ft. of a blightspawn, it must make a DC 16 Will save to avoid being affected as per the spell slow, for as long as the creature remains within the blightspawn's aura and for an additional 1d3 rounds after leaving it. Once a creature successfully saves against the aura, it is immune to that particular blightspawn's aura for 24 hours; otherwise, re-entering the aura forces a creature to save again. In addition, this aura fouls liquids of all types within the area. A creature that drinks anything in a blightspawn's aura (including potions and alchemical elixirs) must make a DC 14 Fortitude save or be nauseated for 1d3 rounds. The save DC is Constitution-based."}],"description":"The blightspawn of Ghlaunder are found most often in places where the Gossamer King's cult is strong, for these creatures must gestate in the body of one of the parasite god's true believers. To the faithful of Ghlaunder, being host to an immature blightspawn is a great honor, for when the monster bursts from the body of its host, the host's consciousness lives on in some way in the blightspawn's mind, almost as if the host had reincarnated into the monster. That cultists who die giving hideous birth to a blightspawn cannot be resurrected lends a bit of weight to this notion, even if the blightspawn themselves have nothing to say on the topic. A cultist carrying an immature blightspawn functions normally in all ways until the creature emerges (typically upon the cultist's death, or at the culmination of certain vile rituals)-except that until then, the cultist can pass on new blightspawn to his or her children. A blightspawn's gestation can last for decades, and in cases in which a child is separated from infected parents, the child might live her entire life without knowing the truth of what awaits her upon death. When a blightspawn emerges from its host, it is immediately fully grown, although its gore-wet wings cannot be used for flight for 1d4 rounds after emerging.","ecology":"","habitat_society":""},{"name":"Bluetip Eurypterid","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"vermin","subtypes":["aquatic"],"init":7,"senses":[{"type":"low-light vision"},{"type":"tremorsense","modifier":"30 ft."}],"ac":19,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+3 Dex, +7 natural, -1 size","hp":52,"hd":"7d8+21","hdvalue":7,"fort":8,"ref":7,"will":3,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":60}],"melee":"2 claws +8 (1d6+4), sting +8 (1d4+4 plus poison)","space":"10 ft.","reach":"10 ft. (15 ft. with sting)","special_attacks":[{"type":"pounce"}],"strength":18,"dexterity":17,"constitution":16,"wisdom":13,"charisma":2,"baseatk":5,"cmb":10,"cmd":23,"feats":[{"feat":"Improved Initiative","type":"bonus"},{"feat":"Lightning Reflexes","type":"bonus"}],"skills":[{"skill":"Swim","value":12}],"sq":[{"type":"amphibious"}],"environments":["temperate oceans","warm oceans"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"Two large pincers grasp at the air before this sleek creature, while a finned tail bristling with a long, thin stinger rises from behind.","group":"Eurypterid","source":"AP 37","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d4 Con; cure 2 consecutive saves."}],"description":"Known to some as sea scorpions, eurypterids are aquatic crustaceans that blur the line between their terrestrial cousins and lobsters. Primeval and voracious, these vermin range in size from relatively harmless ochre eurypterids the size of a dog up to the truly immense spitting eurypterids. There are even rumors of yet larger beasts, called whaleeating eurypterids by sailors. Regardless of their size, all share one thing in common-an aggressive attitude. Eurypterids lash out at anything that might be food, and once they've tasted prey, are single-minded in their pursuit. Although quite at home in the open sea, most eurypterids are capable of scuttling around on land and can exist out of water indefinitely. Unlike rats, eurypterids don't spread disease or cause much damage to most cargos-traits that have led some captains to experiment with seeding colonies of ochre eurypterids in their holds to keep rodent populations under control. Alas, one can often tell the ships that use this tactic by the unusually high number of crewmen with missing fingers.","ecology":"","habitat_society":""},{"name":"Bogwid","cr":5,"xp":1600,"alignment":"CN","size":"Medium","type":"aberration","init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["revolting aura (10 ft., DC 13 Fort)"],"ac":19,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+4 Dex, +5 natural","hp":47,"hd":"5d8+25","hdvalue":5,"fort":5,"ref":5,"will":1,"resists":[{"type":"acid","value":5},{"type":"cold","value":5}],"speed":[{"type":"land","speed":30},{"type":"climb","speed":20},{"type":"swim","speed":20}],"melee":"2 slams +7 (1d6+4 plus nauseating touch)","ranged":"offspring +7 ranged touch (1d2 bleed plus disease)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"ravenous young"}],"strength":19,"dexterity":18,"constitution":18,"intelligence":3,"wisdom":4,"charisma":13,"baseatk":3,"cmb":7,"cmd":21,"cmd_special":"+12 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Stealthy"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":16},{"skill":"Escape Artist","value":6},{"skill":"Perception","value":2},{"skill":"Stealth","value":11,"special":"+19 in swamps"},{"skill":"Swim","value":12}],"sq":[{"type":"amphibious"}],"environments":["any swamps","any underground"],"organizations":["solitary","clutch (1 adult plus 2-8 adolescents)"],"treasure":"none","description_visual":"This nightmare shambles along the ground on eight muscular tentacles that leave behind a clear viscous residue stinking of putrefaction. Its amphibian skin is moist, green-black, and covered in warts and protuberances. On its back, dozens of fist-sized pustules shift and pulsate with nauseating vitality, like sentient oily bubbles threatening to burst.","source":"AP 62","special_abilities":[{"type":"Disease","kind":"Ex","details":"Bogwid Fever: Bite-injury; save Fort DC 16, onset 1 day, frequency 1/day, effect 1d2 Str damage and shaken, cure 2 consecutive saves. The DC save is Constitution-based."},{"type":"Nauseating Touch","kind":"Ex","details":"The bogwid's touch is disgusting. Creatures hit by its slam attack must succeed at a DC 16 Fortitude save or be nauseated for 1 round. The save DC is Constitution-based."},{"type":"Ravenous Young","kind":"Ex","details":"Each round, a bogwid can launch one of the offspring clinging to its back at a target within 10 ft. as a ranged touch attack. On a successful hit, the offspring attaches itself to the target and begins draining blood, automatically dealing 1d2 points of bleed damage each round (and possibly infecting the target with bogwid fever). As a full-round action, a creature can attempt to remove one of these offspring, either by bludgeoning it with a fist or pulling it off. Either way, removing an offspring kills the larval creature. Someone other than the target the offspring is attached to can also perform this action. Anyone using a weapon to kill or remove an attached offspring deals half of the damage to the creature to which the offspring is attached. A bogwid can launch up to 10 offspring per day before it must rest and gestate more larval young."},{"type":"Revolting Aura","kind":"Ex","details":"The bogwid is both visually and odoriferously revolting. Any creature within 10 ft. of a bogwid must succeed at a DC 16 Fortitude save or be sickened. This effect persists as long as the creature is within the aura and for 2 rounds thereafter. A creature that successfully saves isn't subject to the same bogwid's revolting aura for 24 hours. The save DC is Constitution-based."}],"description":"Aberrant beasts of ancient origin, bogwids are loathsome, skulking predators that inhabit the gloomy swamps and damp subterranean places of the world. Looking like a bloated, eight-limbed, greenish-black mix of frog and tentacled beast, this asexual creature is most notorious for the larvae it carries on its back.\n\nEcology\n\nSome scholars suggest the large, muscular body of the bogwid serves as little more than transport for its ravenous young-30 to 40 fist-sized, pustule-like protuberances that cling to its back, inf lating and def lating, shifting and quivering with disturbing vitality. The bogwid attacks with two of its undulating tentacles, the bottoms of which are lined with ragged, bony ridges that can tear hungrily into exposed flesh. However, the more disturbing danger is those pulsating orbs of flesh on its back: larvae that are capable of launching themselves as far as 10 ft. and attaching to creatures with their fanged sucker mouths. Once one of these disgusting things sinks its jagged teeth into flesh, it begins sucking blood and doesn't release its grip until it or the target is dead. When a bogwid makes a kill, several of its young jump upon the warm carcass and feed greedily. If the victim is a Medium or larger creature, these rapacious larvae fight for the opportunity to burrow into the corpse. Over the course of 2 weeks, the burrowed creatures gestate, and the cadaver bloats until an adolescent bogwid (a bogwid with the young template) gruesomely bursts forth. The larger the kill, the more of the bogwid's young can burrow in and hatch out as adolescents; a Large victim can accommodate two larvae, a Huge victim four larvae, a Gargantuan victim eight larvae, and a Colossal victim 16 larvae. A creature smaller than Medium doesn't possess sufficient nutrition for bogwid larvae to gestate properly. As a result, adult bogwids tend to completely consume smaller kills instead of leaving them for the larvae. Bogwids that inhabit seaside haunts are not averse to eating carrion. Indeed, a sizable sea creature whose carcass washes ashore (a whale, for instance) is usually set upon by a nearby bogwid, whose ravenous larvae tunnel their way into the rotting flesh, and several days later erupt like a crawling, monstrous plague. In this way, large clutches of these foul beasts can come to infest coastal areas. The bogwid is generally nocturnal, though it isn't unusual for one to hunt during the day if it has gone a long time without feeding. A bogwid hunts patiently, concealing itself well in its natural habitat by heaping sand, seaweed, vegetation, and other detritus onto its body. Though a bogwid possesses limited intelligence, its animal cunning allows it to employ natural hazards to its advantage, setting up ambushes that cleverly integrate drop-offs, natural pits, and quicksand. As these creatures are also able to climb, it isn't uncommon for bogwids to roost on rocky overhangs or in large trees, dropping down on unsuspecting victims from above. Alchemists pay a significant price for the glands in bogwid tentacles that produce the foul, viscous liquid the creatures excrete. However, these glands are difficult to extract fully intact (DC 25 Heal check) and must be properly stored in water after removal. Appropriately dissected and transported, the glands fetch 25 gp apiece on the right market. Alchemists employ this putrid substance in various formulae to augment their effectiveness.\n\nHabitat & Society\n\nThough great numbers of bogwids take up residence in temperate, swampy, coastal regions and the damp caves that are sometimes found in such places, plenty of the creatures inhabit inland marshes as well. They have been known to adapt to warmer climes, but tropical bogwids are much rarer. The fetid creatures tend not to flourish near major settlements, even if those settlements are in close proximity to the bogwids' natural habitat. The reason is that the presence of a beast like this near a town strikes such revulsion and fear into a population that they quickly post sizable rewards for the destruction of the beast. Rangers who traverse marshes and wet caves eagerly seek out such lucrative bounties. Indeed, the fact that these monsters have not been hunted to extinction is a testimony to their revolting fecundity. As these creatures are asexual, bogwids also tend to be solitary, driving off gestated offspring soon after they reach maturity. Recently matured bogwids seek out their own territory. On the few occasions bogwid clutches form, they most often include a single adult accompanied by two to eight adolescents. These abhorrent creatures have a life expectancy of about 10 years. An older bogwid can be identified by its flesh, which becomes gray-green and increasingly dry as the creature ages. The larvae an older bogwid carries about eventually lead to its own downfall. In the end, the strongest of its young fight off weaker kin and burrow into the dying parent, exploding forth from the corpse in the usual manner 2 weeks later. A bogwid doesn't tolerate other major predators in its territory, hounding them relentlessly until such competitors are killed or find alternate homes for themselves. The bogwid is especially aggressive against crocodiles, which tend to be its chief rivals for prey in swampy regions. In fact, a telltale sign of a bogwid having laid a claim to territory is the discovery of a crocodile corpse lying on its back, the stomach bloated with gestating larvae or torn out as though something exploded from within, suggesting an adolescent bogwid isn't far away.","ecology":"Some scholars suggest the large, muscular body of the bogwid serves as little more than transport for its ravenous young-30 to 40 fist-sized, pustule-like protuberances that cling to its back, inf lating and def lating, shifting and quivering with disturbing vitality. The bogwid attacks with two of its undulating tentacles, the bottoms of which are lined with ragged, bony ridges that can tear hungrily into exposed flesh. However, the more disturbing danger is those pulsating orbs of flesh on its back: larvae that are capable of launching themselves as far as 10 ft. and attaching to creatures with their fanged sucker mouths. Once one of these disgusting things sinks its jagged teeth into flesh, it begins sucking blood and doesn't release its grip until it or the target is dead. When a bogwid makes a kill, several of its young jump upon the warm carcass and feed greedily. If the victim is a Medium or larger creature, these rapacious larvae fight for the opportunity to burrow into the corpse. Over the course of 2 weeks, the burrowed creatures gestate, and the cadaver bloats until an adolescent bogwid (a bogwid with the young template) gruesomely bursts forth. The larger the kill, the more of the bogwid's young can burrow in and hatch out as adolescents; a Large victim can accommodate two larvae, a Huge victim four larvae, a Gargantuan victim eight larvae, and a Colossal victim 16 larvae. A creature smaller than Medium doesn't possess sufficient nutrition for bogwid larvae to gestate properly. As a result, adult bogwids tend to completely consume smaller kills instead of leaving them for the larvae. Bogwids that inhabit seaside haunts are not averse to eating carrion. Indeed, a sizable sea creature whose carcass washes ashore (a whale, for instance) is usually set upon by a nearby bogwid, whose ravenous larvae tunnel their way into the rotting flesh, and several days later erupt like a crawling, monstrous plague. In this way, large clutches of these foul beasts can come to infest coastal areas. The bogwid is generally nocturnal, though it isn't unusual for one to hunt during the day if it has gone a long time without feeding. A bogwid hunts patiently, concealing itself well in its natural habitat by heaping sand, seaweed, vegetation, and other detritus onto its body. Though a bogwid possesses limited intelligence, its animal cunning allows it to employ natural hazards to its advantage, setting up ambushes that cleverly integrate drop-offs, natural pits, and quicksand. As these creatures are also able to climb, it isn't uncommon for bogwids to roost on rocky overhangs or in large trees, dropping down on unsuspecting victims from above. Alchemists pay a significant price for the glands in bogwid tentacles that produce the foul, viscous liquid the creatures excrete. However, these glands are difficult to extract fully intact (DC 25 Heal check) and must be properly stored in water after removal. Appropriately dissected and transported, the glands fetch 25 gp apiece on the right market. Alchemists employ this putrid substance in various formulae to augment their effectiveness.","habitat_society":"Though great numbers of bogwids take up residence in temperate, swampy, coastal regions and the damp caves that are sometimes found in such places, plenty of the creatures inhabit inland marshes as well. They have been known to adapt to warmer climes, but tropical bogwids are much rarer. The fetid creatures tend not to flourish near major settlements, even if those settlements are in close proximity to the bogwids' natural habitat. The reason is that the presence of a beast like this near a town strikes such revulsion and fear into a population that they quickly post sizable rewards for the destruction of the beast. Rangers who traverse marshes and wet caves eagerly seek out such lucrative bounties. Indeed, the fact that these monsters have not been hunted to extinction is a testimony to their revolting fecundity. As these creatures are asexual, bogwids also tend to be solitary, driving off gestated offspring soon after they reach maturity. Recently matured bogwids seek out their own territory. On the few occasions bogwid clutches form, they most often include a single adult accompanied by two to eight adolescents. These abhorrent creatures have a life expectancy of about 10 years. An older bogwid can be identified by its flesh, which becomes gray-green and increasingly dry as the creature ages. The larvae an older bogwid carries about eventually lead to its own downfall. In the end, the strongest of its young fight off weaker kin and burrow into the dying parent, exploding forth from the corpse in the usual manner 2 weeks later. A bogwid doesn't tolerate other major predators in its territory, hounding them relentlessly until such competitors are killed or find alternate homes for themselves. The bogwid is especially aggressive against crocodiles, which tend to be its chief rivals for prey in swampy regions. In fact, a telltale sign of a bogwid having laid a claim to territory is the discovery of a crocodile corpse lying on its back, the stomach bloated with gestating larvae or torn out as though something exploded from within, suggesting an adolescent bogwid isn't far away."},{"name":"Brethedan","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"aberration","init":0,"senses":[{"type":"blindsense","modifier":"120 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":9,"ac_flat_footed":17,"ac_mods":"+8 natural, -1 size","hp":66,"hd":"7d8+35","hdvalue":7,"hp_mods":["regeneration 2 (acid)"],"fort":7,"ref":2,"will":9,"defensive_abilities":["amorphous"],"speed":[{"type":"land","speed":0},{"type":"fly","speed":30,"maneuverability":"good"}],"melee":"2 slams +9 (1d6+4 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"1d6+4"},{"type":"engulf","details":"DC 17, 1d6 acid and paralysis"}],"strength":19,"dexterity":11,"constitution":20,"intelligence":12,"wisdom":14,"charisma":11,"baseatk":5,"cmb":10,"cmb_special":"+4 vs. grapple","cmd":20,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Escape Artist","value":10},{"skill":"Fly","value":12},{"skill":"Handle Animal","value":7},{"skill":"Perception","value":12},{"skill":"Stealth","value":6}],"languages":["Brethedan","telepathy 100 ft."],"sq":[{"type":"adaptation"},{"type":"combine"}],"environments":["any air"],"organizations":["solitary","pair","flotilla (3-8)"],"treasure":"none","description_visual":"This amorphous creature looks like an iridescent, blimp-shaped jellyfish, with a line of tentacles dangling down beneath it.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Adaptation","kind":"Ex","details":"A brethedan's body is extremely mutable, and can adapt to respond to virtually any situation. Once per round as a swift action that doesn't provoke attacks of opportunity, a brethedan can reshape its body and chemistry to adopt any of the following qualities. • It gains resistance 5 against a single energy type (acid, cold, electricity, or fire). • It gains an additional natural attack (bite, tentacle, etc.) with damage appropriate to its size. • Its slam damage type changes to slashing or piercing. • Its slam damage die increases by one step (from 1d6 to 1d8 for most brethedans). • It gains a +4 natural armor bonus to AC. • Its reach increases to 20 ft. A brethedan can only have one modification in effect at any one time-if it selects a new adaptation, it loses any other in effect. More extreme adaptations are also possible (at the GM's discretion), but generally take days or even months to adopt."},{"type":"Combine","kind":"Ex","details":"Thanks to their perfect communication, brethedans can combine to work together as parts of a larger organism. As a swift action, a brethedan adjacent to another can merge with it, becoming a single creature occupying both spaces. The merging brethedan forfeits its actions to augment the other, and adds its hit points (though not its Hit Dice) to the new creature's collective total. At this time, it also chooses one adaptation-the combined creature gains this benefit, and it cannot be changed unless the combined creature uses its single adaptation action each round to do so. Any number of brethedans can merge in this fashion, but each adaptation can be gained only once (though resistances to multiple energy types are allowed). The combined creature retains the ability to swap one adaptation each round (not once per component creature). Splitting into the component creatures again is a full-round action in which all component creatures are released and the remaining hit points are divided evenly. For the purposes of Hit Die-related effects, the Hit Dice of a combined brethedan are equal to those of the component creature with the highest CR."}],"description":"Brethedans are an adaptive race of floating, telepathic creatures that live on gas giant worlds. Though highly intelligent, they disdain physical tools, likely because of the lack of raw materials available in the clouds of their vast homes. Instead, brethedans have evolved to solve problems by combining and modifying their bodies or producing tailored biological agents inside themselves. Though humanoids rarely understand the placid race's obscure and alien goals, brethedans do sometimes travel to and even colonize other gaseous worlds, and are believed to be the first creatures to have tamed oma for use as living spaceships. A typical Brethedan is 10 ft. long and weighs 200 pounds.","ecology":"","habitat_society":""},{"name":"Brimorak","cr":5,"xp":1600,"alignment":"CE","size":"Small","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar","fire"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["smoke breath (5 ft., DC 17)"],"ac":18,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+3 Dex, +4 natural, +1 size","hp":57,"hd":"6d10+24","hdvalue":6,"fort":9,"ref":8,"will":3,"defensive_abilities":["boiling blood"],"dr":"5/cold iron or good","immunities":["electricity","fire"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":16,"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":30}],"melee":"longsword +11 (1d6+3/19-20 plus 1d6 fire), hoof +0  (1d3+1 plus 1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"20-foot line of boiling blood, 5d6 fire damage, Reflex DC 17 half, usable every 1d4 rounds"},{"type":"burning hooves"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"air walk"},{"spell":"fireball"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"summon","details":"level 3, 1 brimorak, 50%"}]},{"frequency":"3/day","spells":[{"spell":"dispel magic"},{"spell":"heat metal"},{"spell":"produce flame"}]}],"strength":17,"dexterity":16,"constitution":19,"intelligence":12,"wisdom":12,"charisma":15,"baseatk":6,"cmb":8,"cmd":21,"feats":[{"feat":"Combat Casting"},{"feat":"Improved Initiative"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":11},{"skill":"Knowledge (engineering)","value":10},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":16}],"languages":["Abyssal","Celestial","Draconic","Ignan","telepathy 100 ft."],"sq":[{"type":"flaming weapon"}],"environments":["any (Abyss; volcanic regions)"],"organizations":["solitary","band (2-6)","platoon (7-16)"],"treasure":"standard (longsword)","description_visual":"Standing just over three ft. tall, this bestial humanoid wears filthy, tattered robes and has blue-gray skin decorated with strange, coiling stripes. Dark fur grows on its head and arms, and its feet end in burning hooves. Its eyes glow as red as the flaming sword it wields in one hand, and its breath fills the surrounding air with noxious gray smoke.","group":"Demon","source":"Book of the Damned V2","special_abilities":[{"type":"Boiling Blood","kind":"Su","details":"A brimorak's blood is boiling hot. It can cough out a hideous amount of this scorching fluid as a breath weapon, but the blood also serves the demon as a defensive ability. Any creature that damages a brimorak with a slashing or piercing melee weapon is sprayed by boiling blood, and takes 1d4 points of fire damage with each successful hit with such a weapon. Creatures using reach weapons are not subject to this damage."},{"type":"Burning Hooves","kind":"Su","details":"A brimorak's hooves burn with fire, leaving scorched hoofprints on wood, stone, and most every other solid surface, yet this supernatural fire doesn't set alight surfaces the demon treads upon. It does make it easier to track a brimorak, though-Survival checks made to track a brimorak gain a +8 circumstance bonus. Brimoraks use their air walk ability to throw creatures off their trail, or to leave their prints in strange places (like atop roofs) to spread fear and terror. Against a prone foe, a brimorak can make two hoof attacks rather than just one."},{"type":"Flaming Weapon","kind":"Su","details":"As a free action, a brimorak can infuse a wielded melee weapon (including a two-handed weapon, but not a second weapon held in the off-hand) with its fiery nature, allowing it to inflict an additional 1d6 points of fire damage with the weapon. This fire damage stacks with any additional fire damage that the weapon might also inflict. The weapon loses this ability if it leaves the demon's grasp."},{"type":"Smoke Breath","kind":"Su","details":"A brimorak's breath manifests as clouds of foul-smelling smoke when it exhales. This breath surrounds the brimorak out to a radius of 5 ft.-while the smoke isn't thick enough to obscure vision or choke foes, it is enough to sicken breathing foes who are not immune to poison. A DC 17 Fortitude save grants immunity to a particular brimorak's breath for 24 hours. The save DC is Constitution-based."}],"description":"Although brimorak demons are generally limited to regions of the Abyss where fire and smoke hold sway, in those regions they are vast in number. Demon lords like Flauros use brimoraks as the primary infantry troops in Abyssal armies-although their command of fire makes them less effective against most fiends, they are particularly devastating against many other foes.\n\nBrimoraks are small in stature, rarely standing over 3 ft. in height, yet surprisingly strong for their size. Those who underestimate these demons often don't live to learn of their errors, for brimoraks are quick to press the advantage against larger enemies after softening them up with fire magic. A brimorak's dense musculature and bones result in unexpected weight as well-one of these creatures usually weighs nearly 200 pounds.\n\nEcology Brimoraks form from the souls of arsonists and those who used fire in life to torture and kill innocent victims- especially witches, heretics, and other such \"criminals\"-via burning at the stake or on a pyre.\n\nAlthough a brimorak isn't damaged by fire, it still feels the pain of fire as long as it lives-the boiling of its own blood is a constant reminder of its sins from a previous life. This state of constant pain is alleviated somewhat after a brimorak uses one of its fire-based spell-like abilities or its breath weapon-while this has no game effect on the demon, the temporary relief does encourage it to use its magic and breath weapon as often as possible in combat.\n\nMany brimoraks become masochistic creatures as a result of the constant pain. In combat they often display little to no regard for their personal safety, provoking attacks of opportunity or ignoring obvious foes for the chance to hurt a helpless foe. Yet this disregard for safety doesn't descend into truly self-destructive behavior-a brimorak with fewer than half its hit points becomes suddenly more careful about its actions. Unlike most demons, who can teleport at will, brimoraks can only use this powerful spell-like ability once per day, and they generally rely upon it to get themselves out of peril rather than to ambush foes.\n\nHabitat & Society On the Abyss, brimoraks usually serve more powerful demons as taskmasters, thugs, or soldiers. These brimorak demons know little more than battle, and when not fighting together against a foe they tend to fight each other in an endless conf lict for superiority.\n\nOn the Material Plane, however, brimoraks take on a much more authoritative role. While most are called via spells like lesser planar ally or lesser planar binding in order to serve mortal spellcasters as minions, now and then a brimorak escapes control and can remain on Golarion. Freed from demonic overlords and binding spellcasters, a brimorak loose on the Material Plane understands that it is viewed as a monster and reacts intelligently-it doesn't immediately revert to an orgy of arson and destruction, but instead retreats into hiding. Free brimoraks prefer to lurk in rundown slums in large cities, in catacombs or sewers, or in remote wilderness regions. Typically, a lone brimorak seeks out a tribe of savage humanoids like goblins, orcs, gnolls, or barbarians and establishes itself as the dominant force for the tribe by killing its leader and several of the tribe's more powerful members-whatever it takes to get the tribe's survivors to bow down before the demon.\n\nAs a result, the majority of brimoraks encountered on the Material Plane are encountered as lone creatures serving as the leaders of tribes of fecund and aggressive humanoids.\n\nOften, and particularly in the case of tribes of superstitious humanoids, the brimorak is regarded as both a chieftain and a god, with tribal adepts actually worshiping the demon out of a mixture of fear and ignorance. Of course, the brimorak is only too pleased to perpetuate such beliefs by requiring frequent sacrifices, using its defensive abilities and spell-like abilities to perform \"miracles,\" and periodically punishing its followers for real or imagined transgressions. Eventually, the brimorak has the tribe so cowed and under his control that he can finally turn to the joys of mayhem by ordering the tribe to take up ill-advised crusades against neighboring tribes or settlements. The brimorak continues to order these attacks on nearby victims until his tribe is destroyed or high-powered opponents arrive to stop it. Brimoraks who are finally confronted by foes capable of defeating them generally don't stay around to defend their followers, but instead simply teleport to some other region, whereupon they begin the process anew by seeking a new tribe of doomed savages to rule.","ecology":"Brimoraks form from the souls of arsonists and those who used fire in life to torture and kill innocent victims- especially witches, heretics, and other such \"criminals\"-via burning at the stake or on a pyre.\n\nAlthough a brimorak isn't damaged by fire, it still feels the pain of fire as long as it lives-the boiling of its own blood is a constant reminder of its sins from a previous life. This state of constant pain is alleviated somewhat after a brimorak uses one of its fire-based spell-like abilities or its breath weapon-while this has no game effect on the demon, the temporary relief does encourage it to use its magic and breath weapon as often as possible in combat.\n\nMany brimoraks become masochistic creatures as a result of the constant pain. In combat they often display little to no regard for their personal safety, provoking attacks of opportunity or ignoring obvious foes for the chance to hurt a helpless foe. Yet this disregard for safety doesn't descend into truly self-destructive behavior-a brimorak with fewer than half its hit points becomes suddenly more careful about its actions. Unlike most demons, who can teleport at will, brimoraks can only use this powerful spell-like ability once per day, and they generally rely upon it to get themselves out of peril rather than to ambush foes.","habitat_society":"On the Abyss, brimoraks usually serve more powerful demons as taskmasters, thugs, or soldiers. These brimorak demons know little more than battle, and when not fighting together against a foe they tend to fight each other in an endless conf lict for superiority.\n\nOn the Material Plane, however, brimoraks take on a much more authoritative role. While most are called via spells like lesser planar ally or lesser planar binding in order to serve mortal spellcasters as minions, now and then a brimorak escapes control and can remain on Golarion. Freed from demonic overlords and binding spellcasters, a brimorak loose on the Material Plane understands that it is viewed as a monster and reacts intelligently-it doesn't immediately revert to an orgy of arson and destruction, but instead retreats into hiding. Free brimoraks prefer to lurk in rundown slums in large cities, in catacombs or sewers, or in remote wilderness regions. Typically, a lone brimorak seeks out a tribe of savage humanoids like goblins, orcs, gnolls, or barbarians and establishes itself as the dominant force for the tribe by killing its leader and several of the tribe's more powerful members-whatever it takes to get the tribe's survivors to bow down before the demon.\n\nAs a result, the majority of brimoraks encountered on the Material Plane are encountered as lone creatures serving as the leaders of tribes of fecund and aggressive humanoids.\n\nOften, and particularly in the case of tribes of superstitious humanoids, the brimorak is regarded as both a chieftain and a god, with tribal adepts actually worshiping the demon out of a mixture of fear and ignorance. Of course, the brimorak is only too pleased to perpetuate such beliefs by requiring frequent sacrifices, using its defensive abilities and spell-like abilities to perform \"miracles,\" and periodically punishing its followers for real or imagined transgressions. Eventually, the brimorak has the tribe so cowed and under his control that he can finally turn to the joys of mayhem by ordering the tribe to take up ill-advised crusades against neighboring tribes or settlements. The brimorak continues to order these attacks on nearby victims until his tribe is destroyed or high-powered opponents arrive to stop it. Brimoraks who are finally confronted by foes capable of defeating them generally don't stay around to defend their followers, but instead simply teleport to some other region, whereupon they begin the process anew by seeking a new tribe of doomed savages to rule."},{"name":"Buggane","cr":5,"xp":1600,"alignment":"CE","size":"Large","type":"monstrous humanoid","init":3,"senses":[{"type":"tremorsense","modifier":"60 ft."},{"type":"scent"}],"ac":18,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"-1 Dex, +10 natural, -1 size","hp":51,"hd":"6d10+18","hdvalue":6,"fort":7,"ref":4,"will":6,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":30}],"melee":"2 claws +11 (1d8+6), gore +11 (1d8+6)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rend","details":"2 claws, 1d8+9"},{"type":"smash and bash"}],"strength":22,"dexterity":9,"constitution":17,"intelligence":6,"wisdom":13,"charisma":6,"baseatk":6,"cmb":13,"cmd":22,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":9},{"skill":"Stealth","value":7,"special":"+15 when underground"}],"languages":["Giant"],"sq":[{"type":"blind"},{"type":"earth distortion"}],"environments":["any underground"],"organizations":["solitary","pair","hunting party (3-5)","clan (6-30)"],"treasure":"standard","description_visual":"This hairless, hunchbacked giant has cruel tusks and two enormous, blunt-clawed fists that look strong enough to shatter stone.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Blind","kind":"Ex","details":"Bugganes are blind. They are immune to gaze attacks, visual effects, illusions, and other attack forms that rely on sight."},{"type":"Earth Distortion","kind":"Su","details":"Once per minute as a swift action, a buggane can empower itself to completely ignore the physicality of stone and metal, enabling it to pass through stone and metal barriers as easily as air. Until the beginning of the buggane's next turn, the buggane has earth glide and takes no damage from stone or metal weapons, or from the natural attacks of creatures of the earth subtype or stone or metal constructs. Additionally, a buggane's melee attacks ignore any AC bonus (including enhancement bonuses) from metal or stone armor and shields. While using earth distortion, the buggane cannot damage stone or metal constructs or creatures of the earth subtype with its natural attacks."},{"type":"Smash and Bash","kind":"Ex","details":"As a free action, a buggane can attempt to trip an opponent it damages with its rend attack without provoking an attack of opportunity. If the trip attempt fails, the buggane cannot be tripped in return. If the trip attempt is successful, the target must succeed at a DC 19 Fortitude save or be stunned for 1 round. The save DC is Strength-based."}],"description":"Bugganes are a race of blind, hairless giants that dwell deep underground. Distantly related to ogres, bugganes share their surface-dwelling cousins' appetite for the flesh of sentient beings, and are coldly efficient killers who tenaciously stalk their prey in absolute silence. Bugganes pursue and slay those who trespass into their well-marked territories, carrying their victims back to their lairs where they are unceremoniously consumed by the entire clan. Dull-witted and savage, bugganes disdain the use of even the most primitive weapons and tools. They rely on their tusks and claws, all of which are capable of shredding flesh, bone, and solid rock with equal ease. Their useless, mole-like eyes react painfully to bright light. A typical buggane stands between 8 and 9 ft. tall and weighs 900 pounds.","ecology":"","habitat_society":""},{"name":"Catrina","cr":5,"xp":1600,"alignment":"N","size":"Medium","type":"outsider","subtypes":["extraplanar","psychopomp"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"spiritsense"}],"auras":["calm emotions (30 ft., DC 17)"],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":51,"hd":"6d10+18","hdvalue":6,"fort":5,"ref":8,"will":9,"dr":"5/adamantine","immunities":["death effects","disease","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"sr":16,"speed":[{"type":"land","speed":30}],"melee":"2 slams +6 (1d8)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"compel condemned"},{"type":"kiss of death"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"death watch"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"invisibility","details":"self only"},{"spell":"speak with dead"}]},{"frequency":"3/day","spells":[{"spell":"major image"}]}],"strength":10,"dexterity":17,"constitution":16,"intelligence":13,"wisdom":14,"charisma":19,"baseatk":6,"cmb":6,"cmd":19,"feats":[{"feat":"Combat Expertise"},{"feat":"Improved Initiative"},{"feat":"Iron Will"}],"skills":[{"skill":"Diplomacy","value":13},{"skill":"Heal","value":8},{"skill":"Knowledge (planes)","value":10},{"skill":"Knowledge (religion)","value":10},{"skill":"Perception","value":11},{"skill":"Stealth","value":12},{"skill":"Use Magic Device","value":10}],"languages":["Abyssal","Celestial","Common","Infernal","tongues","telepathy 100 ft."],"sq":[{"type":"spirit touch"}],"environments":["any (Purgatory)"],"organizations":["solitary","pair","reception (3-10)"],"treasure":"standard","description_visual":"With lengthy curling hair, a dancer's dress, and a bouquet of flowers, this woman remains beautiful, despite having no flesh.","group":"Psychopomp","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Calm Emotions Aura","kind":"Su","details":"A catrina's aura acts like a calm emotions spell with a radius of 30 ft. A creature that succeeds at its save is immune to that catrina's aura for 24 hours. The save DC is Charisma-based."},{"type":"Compel Condemned","kind":"Su","details":"As a standard action, a catrina can force one humanoid within 30 ft. to make a DC 17 Will save or be affected as per the spell dominate person. This ability functions exactly as that spell, but the catrina can only command an affected creature to approach and kiss her. This action isn't considered to be against the target's nature or self-destructive. Any damage taken by the target (other than damage the catrina deals) immediately ends this effect."},{"type":"Kiss of Death","kind":"Su","details":"A catrina can kill a grappled, helpless, or willing target with a long, passionate kiss. The target must succeed at a DC 17 Fortitude save or take 5d6 points of damage. Any creature damaged by the same catrina's kiss for three consecutive rounds instantly dies, regardless of how many hit points it has remaining. Creatures of the old age category take a -2 penalty on saving throws to resist this ability, while those in the venerable age category take a -4 penalty. This is a death effect. The save DCs are Charisma-based."}],"description":"Catrinas welcome the dead into the afterlife, doing what they can to lessen the shock and terror experienced by mortals who haven't accepted their own deaths or who still grieve for themselves. Eschewing the funereal themes and colors preferred by most other psychopomps, catrinas dress in festive shades, surrounding themselves with light and color to dispel a measure of death's gloom. However, they don't disguise their skeletal bodies, for despite any gilding they might put on the moment, they don't seek to disguise the finality of death. A catrina's motivation for easing the transition from life to death has more to do with making the soul's progression calm than compassion for the soul-after all, screaming and outrage disrupts the processing of the dead. Catrinas rarely ever visit the Material Plane, but when they do so it's typically at the command of a more powerful psychopomp or deity of death who seeks to ease the passing of a mortal of singular importance-such as a high-ranking priest of a death goddess. In such instances they serve as companions and ushers into the realm of the dead, not executioners. However, they're capable of serving in both capacities, especially if misguided mortals try to keep them from their duty, using their deadly but painless kisses to end a life in an instant. Catrinas always appear as festively dressed skeletons-usually in women's garb but sometimes in colorful men's formal wear, and usually decorated with or carrying flowers. They don't have true genders, but an individual catrina may have a more masculine or feminine voice and personality. They typically stand between 5 and 6 ft. tall and weigh about 20 to 30 pounds.","ecology":"","habitat_society":""},{"name":"Cayhound","cr":5,"xp":1600,"alignment":"CG","size":"Medium","type":"outsider","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":18,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+2 Dex, +6 natural","hp":51,"hd":"6d10+18","hdvalue":6,"fort":5,"ref":7,"will":6,"dr":"5/cold iron","speed":[{"type":"land","speed":40}],"melee":"bite +11 (1d10+7 plus 1d6 sonic and trip)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"righteous bite"},{"type":"thunderous bark"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"}]},{"frequency":"at-will","spells":[{"spell":"open/close"}]},{"frequency":"3/day","spells":[{"spell":"dimension door"},{"spell":"knock"}]}],"strength":21,"dexterity":15,"constitution":16,"intelligence":8,"wisdom":12,"charisma":13,"baseatk":6,"cmb":11,"cmd":23,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dimensional Agility"},{"feat":"Dimensional Assault"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+14 when jumping"},{"skill":"Intimidate","value":6},{"skill":"Knowledge (planes)","value":6},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":10},{"skill":"Survival","value":8}],"languages":["Celestial"],"sq":[{"type":"unbound"}],"environments":["any (Elysium)"],"organizations":["solitary","pair","pack (3-10)"],"treasure":"none","description_visual":"This reddish-colored mastiff stands eye to eye with most dwarves. Within its powerful frame rumbles the distant sound of thunder.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Righteous Bite","kind":"Su","details":"A cayhound's bite is treated as magical for the purpose of overcoming damage reduction."},{"type":"Thunderous Bark","kind":"Su","details":"Once every 1d6 rounds, a cayhound can bark with the concussive force of a thunderbolt. Every creature within a 15-foot cone-shaped burst must succeed at a DC 14 Fortitude saving throw or take 3d8 points of sonic damage and be knocked prone. A successful saving throw reduces this damage by half and negates being knocked prone. The save DC is Charisma-based."},{"type":"Unbound","kind":"Su","details":"Cayhounds move as if under a continuous freedom of movement spell. They are immune to dimensional anchor, but are affected by dimensional lock normally."}],"description":"Cayhounds, also called leap dogs, are good-aligned outsiders who exemplify strength and freedom. They are descendants of Thunder, the pet mastiff of the Accidental God, Cayden Cailean, who uplifted his faithful companion upon achieving his own apotheosis. Thunder sired the entire cayhound race (including his famous son, Little Thunder) on the golden fields of Elysium. Cayhounds are filled with wild and turbulent forces barely contained within their canine shapes. They are intelligent and feel true lust for and joy in life, including righteous battle, good food, and strong drink. These fiery red hounds stand head to chest with most humans and weigh approximately 250 pounds.\n\nWild as they are, the cayhounds are still more good-aligned than they are chaotic. Like their true master, they are great champions of freedom, and they channel his strength and courage (and a bit of luck) in opposing nefarious schemes wherever they find them. Some ally themselves with azatas, supporting good crusades against the Outer Planes. A pack of cayhounds might seek to disrupt a night hag and her steed's theft of good souls traveling to their intended destinations in the Great Beyond. Single cayhounds may be summoned via lesser planar ally by priests of Cayden Cailean to come to the aid of the faithful.","ecology":"","habitat_society":""},{"name":"Cecaelia","cr":5,"xp":1600,"alignment":"CN","size":"Medium","type":"monstrous humanoid","subtypes":["aquatic"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tentacle sense","modifier":"10 ft."}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 Dex, +4 natural","hp":45,"hd":"6d10+12","hdvalue":6,"fort":4,"ref":9,"will":6,"speed":[{"type":"land","speed":30},{"type":"swim","speed":40}],"speed_mod":"jet 200 ft.","melee":"mwk spear +11 (1d8+4/x3), 2 tentacles +5 (1d4+1 plus grab)","ranged":"mwk spear +12 (1d8+3/x3)","space":"5 ft.","reach":"5 ft. (10 ft. with tentacles)","strength":16,"dexterity":19,"constitution":14,"intelligence":9,"wisdom":12,"charisma":11,"baseatk":6,"cmb":9,"cmb_special":"+4 vs. grapple","cmd":23,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Weapon Focus (spear)"},{"feat":"Weapon Focus (tentacles)"}],"skills":[{"skill":"Stealth","value":13},{"skill":"Survival","value":10},{"skill":"Swim","value":20}],"languages":["Aquan","Common"],"sq":[{"type":"amphibious"}],"environments":["warm water"],"organizations":["solitary","pair","hunting party (2-7)"],"treasure":"standard (masterwork spear)","description_visual":"In place of legs, this handsome humanoid sports an octopus's eight writhing tentacles.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Ink Cloud","kind":"Ex","details":"Once per hour as a standard action, a cecaelia can emit a 10-foot-radius sphere of ink while underwater. This ink cloud provides total concealment and persists for 1 minute."},{"type":"Tentacle Sense","kind":"Ex","details":"As a swift action while swimming and while it isn't grappled or grappling, the cecaelia can spread its tentacles wide to form a sensory net around it. This grants blindsight to a range of 10 ft. and lasts as long as the cecaelia concentrates. While this effect lasts, the creature cannot attack with its tentacles or move."}],"description":"Cecaelias are intelligent human-octopus hybrids that hunt coastlines and ocean reefs. A cecaelia's humanoid upper body varies individually but generally reflects the features of the inhabitants of the\n\nnearest humanoid settlements. Sages think this is an adaptive trait, akin to an octopus's natural camouf lage, allowing cecaelias to mutate within one to two generations to blend in with humanoids sharing their territory. Cecaelia stand 6 ft. tall on land, and weigh just over 200 pounds. They generally live to be 60 years old.\n\nCecaelias don't normally wear clothes, but often carry woven seaweed backpacks. They prefer not to wear armor, though when they do, they prefer light, flexible varieties. Tattoos are a common form of decoration as well.\n\nCecaelias are inquisitive creatures, but wary of strangers, and are quickly frustrated by wordy attempts at diplomacy-which they nearly always view as attempts at deception. As allies, they can be valuable to coastal communities since they often dig up treasures from the seabed that they then trade for fragments of polished glass or bits of \"land fare,\" as they refer to food not taken from the sea.","ecology":"","habitat_society":""},{"name":"Cervapral","cr":5,"xp":1600,"alignment":"NG","size":"Medium","type":"outsider","subtypes":["agathion","extraplanar","good"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"enchantment sense"},{"type":"scent"}],"ac":18,"ac_touch":14,"ac_flat_footed":14,"ac_mods":"+4 Dex, +4 natural","hp":51,"hd":"6d10+18","hdvalue":6,"fort":5,"ref":9,"will":7,"save_mods":"+4 vs. poison","dr":"5/evil or silver","immunities":["electricity","petrification"],"resists":[{"type":"cold","value":10},{"type":"sonic","value":10}],"sr":16,"speed":[{"type":"land","speed":50}],"speed_mod":"sprint","melee":"gore +11 (1d6+2), mwk rapier +11 (1d6+2/18-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"powerful charge","details":"gore +11, 2d6+3"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":9,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"freedom of movement"},{"spell":"speak with animals"}]},{"frequency":"at-will","spells":[{"spell":"animal trance"},{"spell":"liberating command"},{"spell":"message"},{"spell":"remove paralysis"}]},{"frequency":"1/day","spells":[{"spell":"break enchantment"},{"spell":"seeming"}]},{"frequency":"3/day","spells":[{"spell":"knock"},{"spell":"protection from evil"},{"spell":"summon nature's ally III","details":"1 aurochs or 1d3 stags only"}]}],"strength":14,"dexterity":18,"constitution":17,"intelligence":15,"wisdom":15,"charisma":14,"baseatk":6,"cmb":8,"cmd":22,"feats":[{"feat":"Alertness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (gore)"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+18 when jumping"},{"skill":"Bluff","value":11},{"skill":"Disguise","value":11},{"skill":"Escape Artist","value":13},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13,"special":"+23 to detect enchantments"},{"skill":"Stealth","value":13},{"skill":"Survival","value":11}],"languages":["Celestial","Draconic","Infernal","speak with animals","truespeech"],"sq":[{"type":"lay on hands","details":"3d6, 5/day, as a 6th-level paladin"},{"type":"mental purge"},{"type":"mercies","details":"diseased, fatigued"}],"environments":["any land (Nirvana)"],"organizations":["solitary","pair","order (3-6)"],"treasure":"standard (mwk rapier)","description_visual":"This sleek, long-legged, antelope-like figure has majestic pronged horns and ruffs of white fur on its chest and neck.","group":"Agathion","source":"Andoran Birthplace Of Freedom","special_abilities":[{"type":"Enchantment Sense","kind":"Ex","details":"Cervaprals have an innate sense for magical compulsion and control. A cervapral can attempt a Sense Motive check to sense an enchantment as a move action, rather than requiring the normal 1 minute."},{"type":"Mercies","kind":"Su","details":"A cervapral's lay on hands ability removes disease (as remove disease) and fatigue in addition to curing damage."},{"type":"Pronghorn","kind":"Ex","details":"A cervapral's gore attack is considered a primary natural weapon, even when used in conjunction with a weapon attack."},{"type":"Sprint","kind":"Ex","details":"Once per minute, a cervapral can move at 10 times its normal speed (500 ft.) when it makes a charge."}],"description":"Cervaprals embody the essence of liberty and are passionately devoted to both the overthrow of tyranny and the abolition of slavery. They have no moral objection to the concepts of royalty or nobility, but hold any group that is granted authority through inheritance or tradition to a very high standard, insisting that the rights of the ruled must be protected at least as strongly as the rights of the rulers.\n\nCervaprals frequently serve on the Material Plane as willing allies to servants of good who engage in daring raids to free slaves and unjustly held captives. Cervaprals believe nearly any sacrifice is justified to break the chains of bondage, and are equally at home in frontal assaults as they are in stealthy scout missions and infiltrations. They fervently reject the notion that \"the ends justify the means,\" and refuse to accept evil acts in the name of promoting greater good. They are willing to give up considerable personal comfort and safety to promote their goals of freedom and independence for all.\n\nIf called with the lesser planar ally spell, cervaprals generally demand that payment for their services is donated to a cause that fights slavery and supports freedom. Such a cause must not already be closely allied with the spellcaster or her allies. A cervapral who is called to aid in the immediate and direct liberation of prisoners or slaves often halves the payment he requires for granting such assistance.","ecology":"","habitat_society":""},{"name":"Cloaker","cr":5,"xp":1600,"alignment":"CN","size":"Large","type":"aberration","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":12,"ac_flat_footed":16,"ac_mods":"+3 Dex, +7 natural, -1 size","hp":51,"hd":"6d8+24","hdvalue":6,"fort":6,"ref":5,"will":7,"defensive_abilities":["shadow shift"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":40,"maneuverability":"average"}],"melee":"bite +8 (1d6+5), tail slap +3 (1d8+2)","space":"10 ft.","reach":"10 ft. (5 ft. with bite)","special_attacks":[{"type":"engulf"},{"type":"moan"}],"strength":21,"dexterity":16,"constitution":19,"intelligence":14,"wisdom":15,"charisma":14,"baseatk":4,"cmb":10,"cmd":23,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Disguise","value":8,"special":"+16 as cloak"},{"skill":"Fly","value":10},{"skill":"Knowledge (religion)","value":11},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":8}],"languages":["Undercommon"],"environments":["any underground"],"organizations":["solitary","pair","mob (3-6)","flock (7-12)"],"treasure":"standard","description_visual":"This ray-like creature opens a toothy maw and leers with glaring red eyes. Behind it whips a menacing tail of segmented bone.","source":"PFRPG Bestiary","special_abilities":[{"type":"Engulf","kind":"Ex","details":"A cloaker can try to wrap a Medium or smaller creature in its body as a standard action. The cloaker attempts a grapple that doesn't provoke an attack of opportunity. If it wins the grapple check, it establishes a hold and bites the engulfed victim with a +4 bonus on its attack roll. It can still use its whip-like tail to strike at other targets. Attacks that hit an engulfing cloaker deal half their damage to the monster and half to the trapped victim."},{"type":"Moan","kind":"Ex","details":"A cloaker can emit an infrasonic moan as a standard action, with one of four effects. Fear: All creatures in a 30-foot spread must save (Will negates) or become panicked for 2 rounds. Nausea: All creatures in a 30-foot cone must save (Fortitude negates) or fall prone and be nauseated for 1d4+1 rounds. Stupor: A single creature within 30 ft. is affected by hold monster for 5 rounds (Will negates). Unnerve: Anyone within a 60-foot spread automatically takes a -2 penalty on attack and damage rolls. Those in the area for more than 6 consecutive rounds must save (Will negates) or enter a trance, helpless until the moaning stops. Cloakers are immune to these sonic, mind-affecting attacks. A creature that successfully saves against the cloaker's fear, nausea, or unnerve moans cannot be affected by that same moan effect from that cloaker for 24 hours. All of the save DCs against a cloaker's moan are DC 15. Save DCs are Charisma-based."},{"type":"Shadow Shift","kind":"Su","details":"When in dim illumination, a cloaker can manipulate shadows as a free action to create one of three effects: blur (lasts 1d4 rounds, self only), mirror image (CL 6th), or silent image (DC 15, CL 6th, save DC is Charisma-based)."}],"description":"Resembling hideously evil flying manta rays, cloakers are mysterious and paranoid creatures. A typical specimen has an 8-foot wingspan and weighs 100 pounds. A cloaker's motives are hidden and confusing, and they distrust even their own kind. Their strange shape allows them to disguise themselves as a variety of cloaks, tapestries, and other mundane objects, and stories linger of cloakers that ally with other creatures, hitching a ride on their backs and aiding in their ally's protection for their own inscrutable reasons. A rare few are priests of ancient gods, leading cults of cloakers and skum to undertake all manner of hideous rites and working toward singularly sinister goals.","ecology":"","habitat_society":""},{"name":"Crypt Thing","cr":5,"xp":1600,"alignment":"NE","size":"Medium","type":"undead","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["fear (10 ft., frightened for 1d4 rounds, Will DC 16 negates)"],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+2 Dex, +1 dodge, +6 natural","hp":52,"hd":"8d8+16","hdvalue":8,"fort":4,"ref":6,"will":8,"defensive_abilities":["channel resistance +2"],"dr":"10/bludgeoning or magic","immunities":["undead traits"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +10 (1d8+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"teleporting burst"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"quickened dimension door"}]}],"strength":19,"dexterity":14,"intelligence":13,"wisdom":14,"charisma":15,"baseatk":6,"cmb":10,"cmd":23,"feats":[{"feat":"Alertness"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Intimidate","value":13},{"skill":"Knowledge (arcana)","value":6},{"skill":"Knowledge (dungeoneering)","value":5},{"skill":"Knowledge (history)","value":3},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":9}],"languages":["Common"],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"Shreds of leathery flesh cling to this skeletal figure's body, while twin motes of fiery light glow deep in its eye sockets.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Teleporting Burst","kind":"Su","details":"Once per day, a crypt thing can teleport all creatures within 50 ft. of it to randomly determined locations. The crypt thing can only affect creatures of which it is aware and to which it has line of sight. A successful DC 16 Will save negates this effect. An affected creature is teleported in a random direction (roll 1d8, with 1 indicating north and the other numbers indicating compass going clockwise) and a random distance (1d10 x 100 ft.) away from the crypt thing; determine each creature's direction randomly. A teleported creature arrives in the closest open space to the determined destination, but must appear on a solid surface capable of supporting its weight. If there is no appropriate destination in that direction, the creature doesn't teleport at all. The save DC is Charisma-based."}],"description":"Crypt things are undead creatures found guarding tombs, graves, and crypts. Necromancers and other spellcasters create them to guard such areas, and the crypt things never leave their appointed lairs, even to pursue enemies. Their warded area may be a single room or passage, an entire grave complex, or even a city-sized necropolis. Though naturally solitary, multiple crypt things may guard a common area, often in conjunction with constructs or other undead.\n\nA crypt thing only initiates combat if it is attacked or if the object or crypt it is guarding is touched or entered. Until this condition is met, a crypt thing is content to remain motionless-it may even answer questions or otherwise interact with visitors if its master has directed it to do so. Rumors exist of variant crypt things that don't teleport their foes, but instead paralyze opponents and turn them invisible, leaving victims to helplessly watch their allies being torn apart by the angry guardian.\n\nCREATION\n\nA 15th-level spellcaster can create a crypt thing using create undead. The spell also requires the creator or an assistant to be able to cast teleport, greater teleport, or word of recall (or provide this magic from a scroll or other source).","ecology":"","habitat_society":""},{"name":"Curse Devil","cr":5,"xp":1600,"alignment":"LE","size":"Small","type":"outsider","subtypes":["devil","evil","extraplanar","lawful"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"see in darkness"},{"type":"detect magic"},{"type":"detect thoughts"}],"ac":20,"ac_touch":16,"ac_flat_footed":15,"ac_mods":"+4 Dex, +1 dodge, +4 natural, +1 size","hp":39,"hd":"6d10+6","hdvalue":6,"fort":5,"ref":9,"will":7,"defensive_abilities":["natural invisibility"],"dr":"5/cold or silver","immunities":["fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"speed":[{"type":"land","speed":20},{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"2 claws +6 (1d4-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"anathematize"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"detect thoughts"}]},{"frequency":"at-will","spells":[{"spell":"daze"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"mage hand"}]},{"frequency":"1/day","spells":[{"spell":"blindness/deafness"},{"spell":"confusion"},{"spell":"contagion"},{"spell":"summon","details":"level 3, 2 lesser host devils 50%"}]},{"frequency":"3/day","spells":[{"spell":"bestow curse"},{"spell":"suggestion"},{"spell":"touch of idiocy"}]},{"frequency":"5/day","spells":[{"spell":"bane"},{"spell":"chill touch"},{"spell":"doom"}]}],"strength":8,"dexterity":18,"constitution":12,"intelligence":13,"wisdom":15,"charisma":17,"baseatk":6,"cmb":4,"cmd":19,"feats":[{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Bluff","value":12},{"skill":"Fly","value":23},{"skill":"Intimidate","value":12},{"skill":"Perception","value":11},{"skill":"Sense Motive","value":11},{"skill":"Spellcraft","value":10},{"skill":"Stealth","value":17}],"languages":["Infernal","telepathy 100 ft."],"sq":[{"type":"broken curses"},{"type":"infernal bond"}],"environments":["any (Hell)"],"organizations":["solitary"],"treasure":"incidental","description_visual":"This short fiend has mottled pink skin, clawed fingers, and green eyes. It drags a tattered scroll behind its feminine frame.","group":"Devil","source":"Daughters Of Fury","special_abilities":[{"type":"Anathematize","kind":"Su","details":"Once per day as a standard action, a curse devil can temporarily drop its natural invisibility to reveal its true, horrifying form. All creatures within 30 ft. must succeed at a DC 16 Will save or become cursed as bestow curse; additionally, all creatures in the area must succeed at a second DC 16 Will save or have their memories of the event stripped as if by modify memory. The curse devil can resume its invisibility at the end of its turn as a free action. Whether or not the saves are successful, an affected creature is immune to that curse devil's anathematize ability for 24 hours. If its natural invisibility is negated by other methods, the curse devil can't use this ability. Those who can see invisible creatures are immune to this effect. The save DCs are Charisma-based."},{"type":"Broken Curses","kind":"Ex","details":"When a curse devil dies, any lingering curses or harmful effects caused by the devil are undone as if by a miracle spell."},{"type":"Infernal Bond","kind":"Ex","details":"When a curse devil is created by a lesser or greater devil, its creator forges a magical link between the curse devil and a mortal signed to-or implicated in-an infernal contract, such as a mortal who sold her soul to a devil or the first-born child of a mortal who was promised in an infernal bargain). Thereafter, the curse devil can always find the specified mortal as though guided by a locate creature spell with no maximum range. The specified mortal takes a -2 penalty on saving throws against the curse devil's anathematize ability and its spell-like abilities."}],"description":"Curse devils, or phiams, are constructs of Hell that exist outside the infernal hierarchy. They are forged by more powerful devils to hunt down mortals whose souls belong to Hell. When folk speak of \"family curses\" or \"damned fates,\" a curse devil is often pulling strings.\n\nA curse devil is 4 ft. tall and weighs 80 pounds.","ecology":"","habitat_society":""},{"name":"Cyclops","cr":5,"xp":1600,"alignment":"NE","size":"Large","type":"humanoid","subtypes":["giant"],"init":-1,"senses":[{"type":"low-light vision"}],"ac":19,"ac_touch":8,"ac_flat_footed":19,"ac_mods":"+4 armor, -1 Dex, +7 natural, -1 size","hp":65,"hd":"10d8+20","hdvalue":10,"fort":9,"ref":2,"will":4,"defensive_abilities":["ferocity"],"speed":[{"type":"land","speed":30}],"melee":"greataxe +11 (3d6+7/x3)","ranged":"heavy crossbow +5 (2d8/19-20)","space":"10 ft.","reach":"10 ft.","strength":21,"dexterity":8,"constitution":15,"intelligence":10,"wisdom":13,"charisma":8,"baseatk":7,"cmb":13,"cmd":22,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"}],"skills":[{"skill":"Intimidate","value":9},{"skill":"Perception","value":11},{"skill":"Profession (soothsayer)","value":10,"special":"Sense Motive +5"},{"skill":"Survival","value":6}],"languages":["Common","Cyclops","Giant"],"sq":[{"type":"flash of insight"}],"organizations":["solitary","conclave (2-6)","tribe (7-18)"],"treasure":"standard (hide armor, Large greataxe, Large heavy crossbow)","description_visual":"A single huge eye stares from the forehead of this nine-foot-tall giant. Below this sole orb, an even larger mouth gapes like a cave.","source":"PFRPG Bestiary","special_abilities":[{"type":"Flash of Insight","kind":"Su","details":"Once per day as an immediate action, a cyclops can peer into an occluded visual spectrum of possible futures, gaining insight that allows it to select the exact result of one die roll before the roll is made. This effect can alter an action taken by the cyclops only, and cannot be applied to the rolls of others."}],"description":"Many thousands of years ago, the solemn cyclopes ruled vast kingdoms, yet today their glories are long forgotten. What few cyclopes survive seldom aspire higher than protecting their lairs and seeking out their next meals. This latter task occupies a great deal of their focus, for the monstrous appetites and vacuous hunger of the cyclopes control the race's destiny and may have led to their original downfall so long ago. The average cyclops stands 9 ft. tall and weighs 600 pounds. Both males and females are almost completely bald, with stringy patches of dark hair occasionally hanging down from above the ears. A bushy, expressive brow couples with a cyclops's massive eye to make the creature's attitude easily known. Cyclopean history is a vanishing thing inscribed on the crumbling walls of vine-choked lost cities that fell long before even the rise of the elves, when dragons and giants ruled a landscape unspoiled by the petty ephemeral races that rule today. Because things have fallen so far, a given cyclops is less likely to know the near-mythic triumphs of lost ages than even a semi-educated human. Ancient records, the oral traditions of other giantish races, and the scattered accounts of tribal natives of the southern jungles speak of much larger, more primal \"great cyclopes,\" imposing titans with shaggy legs and a massive horn above an inquisitive eye. These creatures are thought to have been either the leaders or the war beasts of the ancient race, and modern cyclopes honor them as elusive, destructive living gods.","ecology":"","habitat_society":""},{"name":"Dandasuka Rakshasa","cr":5,"xp":1600,"alignment":"LE","size":"Small","type":"outsider","subtypes":["native","rakshasa","shapechanger"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+4 Dex, +1 dodge, +3 natural, +1 size","hp":51,"hd":"6d10+18","hdvalue":6,"fort":5,"ref":9,"will":19,"dr":"5/good or piercing","sr":20,"speed":[{"type":"land","speed":30},{"type":"climb","speed":20}],"melee":"bite +8 (1d6+1 plus bleed), 2 claws +8 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d4"},{"type":"detect thoughts","details":"DC 15"},{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":8,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"clairaudience/clairvoyance"}]}],"spellsknown_caster_level":2,"spellsknown_concentration":5,"spellsknown":[{"spell_level":1,"spell_slots":5,"spells":[{"spell":"charm person"},{"spell":"ventriloquism"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"daze"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"}]}],"strength":13,"dexterity":18,"constitution":16,"intelligence":13,"wisdom":12,"charisma":15,"baseatk":6,"cmb":34,"cmd":52,"feats":[{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Spring Attack"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Bluff","value":15},{"skill":"Climb","value":10},{"skill":"Disguise","value":19},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":10},{"skill":"Sleight of Hand","value":10},{"skill":"Stealth","value":17}],"languages":["Common","Infernal","Undercommon"],"sq":[{"type":"change shape","details":"any humanoid; alter self"}],"environments":["any"],"organizations":["solitary","pair","murder (3-10)"],"treasure":"standard","description_visual":"This small creature looks like a well-dressed and jewelry-bedecked fiendish gnome, its face mostly mouth and fangs.","group":"Rakshasa","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Spells","details":"A dandasuka casts arcane spells as a 2nd-level sorcerer."}],"description":"Dandasukas, also known as \"biters\" among rakshasas, serve as spies and assassins. They often appear as part of a rakshasa's retinue or secret network. Born to manipulate and murder, they revel in their work and delight in the sight of blood. Thus, dandasukas go about their work cheerfully, laughing as they manipulate foes and butcher victims.\n\nAll dandasukas are restless and energetic. They crave activity and entertainment, preferring the sick and cruel to conventional fare. Dandasuka pranks are rarely amusing for the victim.\n\nMonstrous hunger gnaws at the hyperactive dandasuka's body, making the creature crave humanoid flesh and blood. When such blood is spilled, a dandasuka is often not able to contain its fiendish appetite. It might lick a bloody blade, lap up fallen drops, or even take a bite out of a fallen foe at the expense of a more tactically sound option in a fight. A dandasuka settles for other meat when it must, but it always prefers humanoid flesh.\n\nMurder and mayhem are not the only duties of a dandasuka. Stronger rakshasas dispatch dandasukas as emissaries and servants to allies. Despite their usual disorderly habits, they bargain good-naturedly and in good faith, only implying dire consequences for noncompliance. Dandasuka negotiators efficiently take care of impasses if no favorable resolution can be reached. Similarly, dandasuka retainers serving rakshasa allies curb their fiendish ways as best they can, though their employers would still do well to keep them amused and fed. One has to be careful of keeping dandasukas too pleased, however, since they are known to take unwanted initiative because of off-hand remarks, such as idle wishes that a certain person were dead.\n\nDandasuka greed extends from amusements and food to wealth. All dandasukas love comfort, fine clothing, and shiny baubles. Most of them wear as much jewelry as they possibly can without looking ridiculous, and some cross that line. A dandasuka is 3 ft. tall and weighs 55 pounds.","ecology":"","habitat_society":""},{"name":"Dark Caller","cr":5,"xp":1600,"alignment":"CE","size":"Medium","type":"humanoid","subtypes":["dark folk"],"init":3,"senses":[{"type":"detect magic"},{"type":"see in darkness"}],"ac":17,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 dodge, +3 natural","hp":52,"hd":"8d8+16","hdvalue":8,"fort":4,"ref":9,"will":1,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"mwk dagger +10 (1d4+2/19-20 plus black smear poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"sneak attack","details":"+2d6"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"bleed"}]},{"frequency":"1/day","spells":[{"spell":"shadow conjuration"}]},{"frequency":"3/day","spells":[{"spell":"deeper darkness"},{"spell":"shadow step"}]}],"strength":14,"dexterity":17,"constitution":14,"intelligence":13,"wisdom":13,"charisma":18,"baseatk":6,"cmb":1,"cmd":14,"feats":[{"feat":"Augment Summoning"},{"feat":"Dodge"},{"feat":"Spell Focus (conjuration)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Climb","value":6},{"skill":"Intimidate","value":5},{"skill":"Knowledge (arcana)","value":9},{"skill":"Knowledge (planes)","value":9},{"skill":"Perception","value":8},{"skill":"Stealth","value":10},{"skill":"Use Magic Device","value":5}],"languages":["Dark Folk","Undercommon"],"sq":[{"type":"poison use"},{"type":"shadow ritual"}],"environments":["any underground"],"organizations":["solitary","pair","gang (1 plus 2-5 dark stalkers)","clan (20-80 dark creepers plus 1 dark stalker and dark caller per 20 dark creepers)"],"treasure":"standard","description_visual":"Wrapped in tatters of dark musty robes, this humanoid figure weaves malevolent magic.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Death Throes","kind":"Su","details":"When a dark caller is slain, its body bursts into shreds of blisteringly cold shadows, leaving its gear in a heap on the ground. All creatures within a 10-foot burst take 1d4 points of Strength damage and are staggered for 1 round. A successful DC 16 Fortitude save halves the Strength damage and negates the staggered effect. This ability damage is temporary and an affected creature's Strength returns to normal after 3d10 minutes. The save DC is Constitution-based."},{"type":"Shadow Ritual","kind":"Su","details":"Three dark callers can collaborate on a ritual that calls an owb to their service. The ritual takes 1 hour to complete. If the dark callers involved are distracted in any way, the attempt is ruined and the ritual must begin anew. Once called to their service, the owb serves them for 24 hours. Though the owb is free-willed, it follows orders to the best of its ability."}],"description":"Dark callers hold a position in dark folk society similar to that of lay priests. Dark callers are named for their role in summoning otherworldly creatures called owbs to oversee important rites in their shadowed communities deep underground. Dark callers perform rituals that bring these creatures forth to preside over all manner of ceremonies the dark folk perform, but the most important is the blanching. When dark folk are born, they are exposed to the sinister touch of the owb's curse of darkness ability, which saps all color and light from the infant dark folk. It's during this ritual that the infant's potential is judged. From that moment on, the youngling grows into one of the various types of dark folk. Dark callers are the least physically malformed of the dark folk, but their minds are more twisted than those of their cousins. They're cruel and inscrutable to most, and they lead their kind alongside dark stalkers, controlling vast underground communities of these strange humanoids. In many cases, one dark stalker and one dark caller lead a clan. A dark caller is highly superstitious, seeing omens in all things. He constantly performs strange rituals whose results are interpreted only by him, then passed to the dark stalker with he's paired with in leadership. Dark callers are typically 6 ft. tall and weigh slightly under 100 pounds. Despite their lanky frames, they're quite strong, though they avoid physical confrontation. Instead, they'll use their limited authority to command dark creepers to fight for them, or at least distract attackers while the dark callers cast spells.","ecology":"","habitat_society":"","gear":"mwk dagger, black smear [2 doses]"},{"name":"Dawn Piper","cr":5,"xp":1600,"alignment":"CN","size":"Medium","type":"fey","subtypes":["extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"auras":["terrible beauty (30 ft., DC 16)"],"ac":18,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+4 Dex, +1 dodge, +3 natural","hp":45,"hd":"7d6+21","hdvalue":7,"fort":5,"ref":9,"will":3,"dr":"5/cold iron","sr":16,"speed":[{"type":"land","speed":30}],"melee":"mwk rapier +8 (1d6+2/18-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"dissonance","details":"every 1d4 rounds, 15-ft. cone, 6d6 sonic damage, Reflex DC 16 half"},{"type":"elemental font"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"overwhelming grief"},{"spell":"rage"}]},{"frequency":"3/day","spells":[{"spell":"calm emotions"},{"spell":"delusional pride"},{"spell":"reckless infatuation"},{"spell":"unadulterated loathing"},{"spell":"unnatural lust"}]}],"strength":15,"dexterity":18,"constitution":16,"intelligence":14,"wisdom":15,"charisma":17,"baseatk":3,"cmb":12,"cmd":23,"cmd_special":"can't be tripped","feats":[{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Bluff","value":11},{"skill":"Craft (musical instruments)","value":6},{"skill":"Diplomacy","value":10},{"skill":"Knowledge (nature)","value":10},{"skill":"Knowledge (planes)","value":8},{"skill":"Perception","value":11},{"skill":"Perform (wind)","value":12},{"skill":"Sense Motive","value":9},{"skill":"Spellcraft","value":8},{"skill":"Stealth","value":10},{"skill":"Use Magic Device","value":13}],"languages":["Aklo","Common","Sylvan"],"environments":["any forests"],"organizations":["solitary","duet","choir (3, 5, or 7)"],"treasure":"standard (mwk rapier, mwk musical instrument)","description_visual":"Eldritch energy burns within the eyes of this humanoid figure. Strangely colored hair crowns her head like a torch, and gleaming white teeth shine from her grin. The creature cradles a pipe in her long, graceful fingers.","source":"AP 68","special_abilities":[{"type":"Dissonance","kind":"Su","details":"Every 1d4 rounds as a standard action, a dawn piper can use a musical instrument to unleash a deadly torrent of sonic vibrations that tears at the very physicality of its enemies. This is similar to a breath weapon that deals 6d6 points of sonic damage in a 15-ft. cone (Reflex DC 16 half). A dawn piper must be in possession of a musical instrument in order to use this ability. The save DC is Charisma-based."},{"type":"Elemental Font","kind":"Su","details":"A dawn piper can infuse a 40-foot-radius area with the primal qualities of the First World. The creation of an elemental font requires a musical instrument and a musical ritual lasting 8 hours. As long as the piper returns to it every 24 hours, a font can persist forever, but it is destroyed immediately upon the creator's death. A dawn piper can also destroy its own font as a full-round action. The dawn piper gains additional spell-like abilities based on a single element while within range of its elemental font. Dimensional anchor and dimensional lock stop the flow of power, preventing the piper from using the additional spell-like abilities. The save DCs are Charisma-based, and the spell-like abilities are cast at caster level 7th. Air: 2/day-fly, gust of wind (DC 15), shocking grasp Earth: 2/day-grease (DC 14), spiked pit (DC 16), stone call Fire: 2/day-burning hands (DC 14), fireball (DC 16), pyrotechnics (DC 15) Water: 2/day-aqueous orb (DC 16), hydraulic push, slipstream."},{"type":"Terrible Beauty","kind":"Su","details":"As a standard action, a dawn piper can surround itself in an intense aura of magnificence that is too potent for non-fey to withstand. Non-fey creatures within a 30-foot radius of the dawn piper must succeed at a DC 16 Will save or be blinded or deafened for 1d4 rounds (the piper's choice, but the effect is consistent for all affected creatures), and take 1 point of bleed damage from their eyes or ears (depending on the specific effect). This aura lasts 1 full round, and a creature that succeeds at its saving throw cannot be affected again for 24 hours. This is a visual or auditory, mind-affecting effect. A dawn piper requires a musical instrument in order to create this aura. The save DC for this ability is Charisma-based."}],"description":"Strange and enigmatic creatures from the First World, dawn pipers are unmistakably humanoid and share some of the same delicate features of half-elves. But dawn pipers' otherworldly nature becomes evident when one looks at the creatures' eyes, which burn with a strange light. Their skin is smooth, free of blemish or body hair, and radiant. Their hair moves constantly, like the flickering flames of a torch in the breeze, and seems to express a seasonal theme in coloration. Their faces are portraits of every emotion that passes through their consciousness; joy, loss, and murder may all dance across their expressions in a matter of moments. Only when a dawn piper is asleep or plays a soothing melody on its pipes does its expression become static and human-and through such songs, dawn pipers' heartbreaking beauty becomes truly evident.\n\nEcology\n\nEarly on in their primordial realm, dawn pipers toyed with emotion and its effects on the mutable nature of the First World. They marveled at how their plane could be transformed by an expression of strong will and passion. Their name allegedly stems from being the \"musicians at the dawn of Creation.\" Yet, coming from the First World, they are soulless creatures and immortal on their home plane. Dawn pipers cannot hold on to their feelings, and with the passage of time their emotions slip away from them like sand through their fingers. Through study and experimentation, dawn pipers devised a means to cheat their own ephemeral nature through music. The pipers associate emotion with melody, and when their passions leave them, they recreate them from memory through their music. While music is an exercise in creativity, it also has elements of structure and pattern, and that is what the pipers retain long after other fleeting experiences fade. This is no small advantage in the highly morphic environment of the First World, allowing them to knead and shape portions of their home through the use of music and emotion. Though the dawn pipers have no strict elemental association, they may also use their music to create an elemental font through which they can channel and shape the energies of the Inner Planes.\n\nDawn pipers are not wholly flesh and bone, as a raw creative power also infuses them-the source of the burning light that shines out of their eyes. Despite their transitory emotions, there is enough definition imposed upon their existence that they remain subject to physical laws. If killed in the First World, dawn pipers don't truly die but are reborn. The same cannot be said when they expire on other worlds.\n\nHabitat & Society\n\nDawn pipers have no formal, overarching society of their own, but they sometimes form small partnerships called choirs, which always have a prime number of members. They act as entertainers, advisors, and shapers among the fey of the First World. Outsiders find them easy to dismiss as slaves to the very emotions they conjure, but nothing could be less true. Dawn pipers are usually shrewd and manipulative, and merely play at the role of a manic social gadf ly. It is said that azatas can sometimes reason with them when they meet; otherwise, dawn pipers jockey for power and inf luence with fey beings greater than themselves. Dawn pipers are great proponents of subsuming parts of the Material Plane into the First World, yet few such incursions ever happen because they are reluctant to travel to the Material Plane, where they are mortal, unless on a matter of great importance. They rarely take mortal lovers as such dalliances seldom end happily-though when they do partake in them, there are always new melodies waiting to be improvised by which to remember the forsaken relationships.\n\nDawn Piper Choirs\n\nA choir of dawn pipers can use their elemental fonts to absorb a part of the Material Plane into the First World by creating a reality siphon. To open a reality siphon, at least three dawn pipers must perform a musical ritual lasting 8 hours. Each piper must have its own elemental font prior to the start of the ritual, and no font can be more than 400 ft. from another. At the conclusion of the ritual, the reality siphon appears, creating a 10-foot-radius hemispherical area of twisted reality that functions as an antilife shell (CL 9th). After the ritual is complete, the pipers are free to take other actions until the reality siphon fully manifests. Over the course of 1 week, the reality siphon gradually expands until it encompasses a 400-foot-radius area, at which point everything in the area encompassed by the reality siphon is fully subsumed into the First World. Destroying the elemental fonts sustaining the reality siphon before it fully manifests causes it to implode upon itself, destroying the siphon and preventing it from drawing part of the Material Plane into the First World.\n\nAt the GM's discretion, certain more powerful choirs may have additional spell-like abilities, similar to the abilities a hag's coven possesses. They may also have powers related to the alteration of their environment in the First World.","ecology":"Early on in their primordial realm, dawn pipers toyed with emotion and its effects on the mutable nature of the First World. They marveled at how their plane could be transformed by an expression of strong will and passion. Their name allegedly stems from being the \"musicians at the dawn of Creation.\" Yet, coming from the First World, they are soulless creatures and immortal on their home plane. Dawn pipers cannot hold on to their feelings, and with the passage of time their emotions slip away from them like sand through their fingers. Through study and experimentation, dawn pipers devised a means to cheat their own ephemeral nature through music. The pipers associate emotion with melody, and when their passions leave them, they recreate them from memory through their music. While music is an exercise in creativity, it also has elements of structure and pattern, and that is what the pipers retain long after other fleeting experiences fade. This is no small advantage in the highly morphic environment of the First World, allowing them to knead and shape portions of their home through the use of music and emotion. Though the dawn pipers have no strict elemental association, they may also use their music to create an elemental font through which they can channel and shape the energies of the Inner Planes.\n\nDawn pipers are not wholly flesh and bone, as a raw creative power also infuses them-the source of the burning light that shines out of their eyes. Despite their transitory emotions, there is enough definition imposed upon their existence that they remain subject to physical laws. If killed in the First World, dawn pipers don't truly die but are reborn. The same cannot be said when they expire on other worlds.","habitat_society":"Dawn pipers have no formal, overarching society of their own, but they sometimes form small partnerships called choirs, which always have a prime number of members. They act as entertainers, advisors, and shapers among the fey of the First World. Outsiders find them easy to dismiss as slaves to the very emotions they conjure, but nothing could be less true. Dawn pipers are usually shrewd and manipulative, and merely play at the role of a manic social gadf ly. It is said that azatas can sometimes reason with them when they meet; otherwise, dawn pipers jockey for power and inf luence with fey beings greater than themselves. Dawn pipers are great proponents of subsuming parts of the Material Plane into the First World, yet few such incursions ever happen because they are reluctant to travel to the Material Plane, where they are mortal, unless on a matter of great importance. They rarely take mortal lovers as such dalliances seldom end happily-though when they do partake in them, there are always new melodies waiting to be improvised by which to remember the forsaken relationships.\n\nDawn Piper Choirs\n\nA choir of dawn pipers can use their elemental fonts to absorb a part of the Material Plane into the First World by creating a reality siphon. To open a reality siphon, at least three dawn pipers must perform a musical ritual lasting 8 hours. Each piper must have its own elemental font prior to the start of the ritual, and no font can be more than 400 ft. from another. At the conclusion of the ritual, the reality siphon appears, creating a 10-foot-radius hemispherical area of twisted reality that functions as an antilife shell (CL 9th). After the ritual is complete, the pipers are free to take other actions until the reality siphon fully manifests. Over the course of 1 week, the reality siphon gradually expands until it encompasses a 400-foot-radius area, at which point everything in the area encompassed by the reality siphon is fully subsumed into the First World. Destroying the elemental fonts sustaining the reality siphon before it fully manifests causes it to implode upon itself, destroying the siphon and preventing it from drawing part of the Material Plane into the First World.\n\nAt the GM's discretion, certain more powerful choirs may have additional spell-like abilities, similar to the abilities a hag's coven possesses. They may also have powers related to the alteration of their environment in the First World."},{"name":"Deadfall Dweller","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"magical beast","init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":57,"hd":"6d10+24","hdvalue":6,"fort":8,"ref":6,"will":5,"immunities":["acid"],"weaknesses":["vulnerable to electricity"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":10}],"melee":"bite +10 (1d6+5 plus poison), 2 limbs +5 (1d4+2)","ranged":"spittle +6 (1d6 acid plus entrap)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"entrap","details":"DC 16, 1d4 rounds, hardness 3, hp 6"},{"type":"implant"},{"type":"spittle"}],"strength":21,"dexterity":13,"constitution":16,"intelligence":5,"wisdom":12,"charisma":10,"baseatk":6,"cmb":17,"cmb_special":"+4 vs. grapple","cmd":29,"cmd_special":"+12 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":17},{"skill":"Perception","value":7},{"skill":"Stealth","value":2,"special":"+10 in forests or swamps"}],"languages":["Sylvan (can't speak)"],"sq":[{"type":"freeze"}],"environments":["temperate forests","temperate swamps"],"organizations":["solitary","brood (2-5)","ruin (6-12)"],"treasure":"standard","description_visual":"This creature resembles a fallen tree trunk that walks upon dozens of tiny, barbed branches and shambles like a spider.","source":"Tears At Bitter Manor","special_abilities":[{"type":"Implant","kind":"Ex","details":"A deadfall dweller can inject 1d3 larvae into a helpless creature as a full-round action. Excretions from these larvae have a paralyzing effect, leaving the host helpless until the larvae mature into young deadfall dwellers that erupt from the host's body, killing it. Each day, an impregnated host must attempt a DC 16 Fortitude save. If the host succeeds at the saving throw, it is no longer helpless, but is still impregnated. If it fails, it takes 1 point of Constitution drain and remains helpless for another day. All of the larvae in an impregnated creature can be destroyed with a remove disease spell. Alternatively, a creature can take 10 minutes to attempt a DC 20 Heal check to remove a single larva. This check can be attempted multiple times, but each attempt deals 1d6 points of damage to the host. The save DC is Constitution-based."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 16; frequency 1/round for 6 rounds; effect 1d3 Dexterity damage; cure 1 save."},{"type":"Spittle","kind":"Ex","details":"As a swift action, a deadfall dweller can emit a stream of corrosive spittle at one target within 30 ft. On a successful attack, the target takes 1d6 points of acid damage, and must save to avoid being entrapped by the solidifying mucus."}],"description":"Deadfall dwellers are dangerous ambush predators most commonly encountered in the old forests and forgotten marshes of eastern Avistan. They make their homes among fallen stands of trees, where they take advantage of a unique form of camouflage. Hungry deadfall dwellers fold their many sticklike legs under themselves, collapsing against large tree trunks or simply lying on the ground. When a warm-blooded creature happens by, a deadfall dweller straightens its legs to pursue, and bellows out a spray of acidic mucus that paralyzes the victim in its tracks. The beast then advances to attack with its poisonous bite and sharp, scraping appendages.\n\nDeadfall dwellers reproduce by immobilizing prey with repeated applications of acidic spray, then implanting a clutch of eggs within the paralyzed host. The larval dwellers keep their host immobilized while they absorb moisture from its body. After the dwellers grow in size, they emerge from the husk of their host, whose flesh by that point resembles the shriveled bark of a dead tree.\n\nMost deadfall dwellers have a mottled green-brown carapace, the better to fit into their typical surroundings. A few have been reported in colder climates, with white-gray exoskeletons and freezing spittle. An average deadfall dweller stretches 11 ft. long, stands 6 ft. tall, and weighs 600 pounds.","ecology":"","habitat_society":""},{"name":"Derhii","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"monstrous humanoid","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":18,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+3 Dex, +6 natural, -1 size","hp":59,"hd":"7d10+21","hdvalue":7,"fort":5,"ref":8,"will":6,"speed":[{"type":"land","speed":30},{"type":"climb","speed":30},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"mwk falchion +12 (2d6+7/18-20) or 2 slams +11 (1d6+5)","ranged":"javelin +9 (1d8+5)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"aerial charge"},{"type":"knockdown"}],"strength":21,"dexterity":16,"constitution":17,"intelligence":9,"wisdom":12,"charisma":10,"baseatk":7,"cmb":1,"cmd":13,"feats":[{"feat":"Acrobatic"},{"feat":"Combat Reflexes"},{"feat":"Iron Will"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Climb","value":13},{"skill":"Fly","value":9},{"skill":"Perception","value":14}],"languages":["Auran","Common"],"sq":[{"type":"booming voice"}],"environments":["warm forests","warm mountains"],"organizations":["solitary","pair","troop (3-5)","tribe (8-48)"],"treasure":"standard (masterwork falchion, 4 javelins)","description_visual":"Powerful black wings beat from the back of this large ape, which carries a wickedly curved sword in its simian hands.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Aerial Charge","kind":"Ex","details":"When airborne, a derhii can dive at twice its normal flying speed. This is the equivalent of a charge, granting a +2 bonus on the attack roll and a -2 penalty to AC."},{"type":"Booming Voice","kind":"Ex","details":"A derhii can use its own booming voice as a signal. The sound can be heard up to 12 miles away as a thrumming in the air that conveys 20 words of information in 5 minutes."},{"type":"Knockdown","kind":"Ex","details":"When a derhii confirms a critical hit with a two-handed weapon, it has a chance to knock an opponent prone in addition to the damage dealt by the critical hit. If the derhii's confirmation roll exceeds its opponent's CMD, the opponent is knocked prone as if from the trip combat maneuver. This doesn't provoke an attack of opportunity, nor can the derhii be tripped if the confirmation roll fails to exceed the CMD."}],"description":"The derhii, or flying ape, is a carnivorous and dangerous form of the gentler earthbound ape. Derhii resemble gorillas with the enormous black-and-gray wings of buzzards or vultures. They stand 9 ft. tall and weigh 400 pounds.\n\nDerhii form relatively small groupings known as troops, which usually consist of a single adult male, several adult females, and their offspring. Occasionally, multiple males or females band together in single-gender troops with no young, but such groupings are usually formed for a specific purpose, such as hunting, raiding, or war, and break up when they have fulfilled that purpose. Multiple troops of derhii form large primitive tribes, usually under the rule of a single powerful chieftain.\n\nDerhii often roost in jungle canopies and in cliff dwellings, preferring nests woven in tall trees or cliff-side caves high above ground level. From these roosts, derhii sometimes demand tribute from lesser apes, while allying themselves with even more powerful flying creatures, such as dragons or dragonnes. Occasionally, derhii can be found inhabiting crumbling and overgrown ruins hidden deep in the jungle.\n\nDerhii are carnivorous by nature and hunters by preference, attacking prey from high above with javelins thrown from their powerful arms before descending to finish things off with their blades, but when meat is scarce, they eat fruits and roots or whatever else they can forage.","ecology":"","habitat_society":""},{"name":"Dire Lion","cr":5,"xp":1600,"alignment":"N","size":"Large","type":"animal","init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 Dex, +4 natural, -1 size","hp":60,"hd":"8d8+24","hdvalue":8,"fort":9,"ref":8,"will":2,"speed":[{"type":"land","speed":40}],"melee":"bite +12 (1d8+7 plus grab), 2 claws +13 (1d6+7)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"rake","details":"2 claws +13, 1d6+7"}],"strength":25,"dexterity":15,"constitution":17,"intelligence":2,"wisdom":12,"charisma":10,"baseatk":6,"cmb":8,"cmd":20,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":11},{"skill":"Perception","value":11},{"skill":"Stealth","value":7,"special":"+11 in undergrowth"}],"environments":["warm hills","warm plains"],"organizations":["solitary","pair","pride (3-8)"],"treasure":"incidental","description_visual":"This immense spotted lion stands as tall as a man at the shoulder, its fur matted with the blood of its victims.","group":"Lion","source":"PFRPG Bestiary","description":"Dire lions, known locally as spotted lions or cave lions, are immense predators that can grow up to 15 ft. long and weigh up to 3,500 pounds. Although they are merely animals, these large creatures seem to take an almost sadistic glee in playing with and tormenting their prey before eventually devouring it. As a result, many tribes view dire lions as the spawn of evil gods, and hunt them down as soon as their presence in a region becomes obvious.","ecology":"","habitat_society":""}];
